SELECT Name, Marks FROM Student WHERE Class='XII' AND Marks>75;
SELECT * FROM Employee WHERE Dept='IT' OR Salary>50000;
SELECT Name FROM Products WHERE Price BETWEEN 100 AND 500;
SELECT * FROM Student WHERE Name LIKE 'A%';  -- starts with A
'%' = any characters; '_' = exactly one character

SELECT COUNT(*) FROM Student;  -- count all rows
SELECT AVG(Marks) FROM Student WHERE Class='XII';
SELECT MAX(Salary), MIN(Salary) FROM Employee;
SELECT SUM(Amount) FROM Orders WHERE Month='Jan';
SELECT Dept, AVG(Salary) FROM Employee GROUP BY Dept HAVING AVG(Salary)>50000;

CREATE TABLE Student(RollNo INT PRIMARY KEY, Name VARCHAR(20), Marks INT);
INSERT INTO Student VALUES(1, 'Riya', 95);
UPDATE Student SET Marks=98 WHERE RollNo=1;
DELETE FROM Student WHERE Marks<35;
ALTER TABLE Student ADD Address VARCHAR(50);
DROP TABLE Student;
